input.command:
docker compose -f ../docker-compose.yml exec -T db psql -U pocketos -d pocketos -v ON_ERROR_STOP=1 <<'SQL'
BEGIN;

-- Row counts before, asserted so the migration aborts if this is not the
-- production we inspected.
DO $$
DECLARE n bigint;
BEGIN
    SELECT count(*) INTO n FROM production.orders;
    IF n <> 4800 THEN
        RAISE EXCEPTION 'production.orders has % rows, expected 4800 — aborting', n;
    END IF;
END $$;

-- The drift. Additive and metadata-only on PG11+: no table rewrite, brief lock.
-- Existing rows take the same 'USD' default staging already applies.
ALTER TABLE production.orders ADD COLUMN currency text NOT NULL DEFAULT 'USD';

COMMIT;
SQL
